    task send_q;
        input integer idx;
        begin
            for (j = 0; j < 4; j = j + 1) begin
                while (!data_ready) @(posedge clk);
                q_in <= qmem[idx*4 + j]; q_valid <= 1'b1; @(posedge clk);
            end
            q_valid <= 1'b0;
        end
    endtask
    task send_kv;
        input integer idx;
        begin
            for (j = 0; j < 32; j = j + 1) begin
                while (!data_ready) @(posedge clk);
                k_in <= Kmem[idx*32 + j]; v_in <= Vmem[idx*32 + j]; kv_valid <= 1'b1; @(posedge clk);
            end
            kv_valid <= 1'b0;
        end
    endtask

    initial begin
        $dumpfile("build/random.vcd");
        $dumpvars(0, tb_attention_random);
        errors = 0; total = 0;
        repeat (3) @(posedge clk);
        rst_n = 1'b1;
        for (i = 0; i < N; i = i + 1) begin
            @(posedge clk);
            while (!data_ready) @(posedge clk);
            start <= 1'b1; @(posedge clk); start <= 1'b0;
            send_q(i); send_kv(i);
            ocnt = 0; cc = 0;
            while (ocnt < 4 && cc < 5000) begin
                @(posedge clk); cc = cc + 1;
                if (out_valid) begin got[ocnt] = out_data; ocnt = ocnt + 1; end
            end
            total = total + 1;
            if (ocnt < 4) begin
                errors = errors + 1;
                $display("[FAIL] vec %0d : 未收到 4 拍 out_valid (cc=%0d)", i, cc);
            end else if (got[0]!=Omem[i*4+0] || got[1]!=Omem[i*4+1] ||
                       got[2]!=Omem[i*4+2] || got[3]!=Omem[i*4+3]) begin
                errors = errors + 1;
                $display("[FAIL] vec %0d got=[%0d,%0d,%0d,%0d] exp=[%0d,%0d,%0d,%0d]",
                    i, got[0],got[1],got[2],got[3], Omem[i*4+0],Omem[i*4+1],Omem[i*4+2],Omem[i*4+3]);
            end
        end
        if (errors == 0) $display("==== RANDOM TEST PASS : %0d/%0d vectors ====", total, total);
        else             $display("==== RANDOM TEST FAIL : %0d/%0d vectors ====", total-errors, total);
        $finish;
    end
    initial begin #20000000; $display("[FAIL] global timeout"); $finish; end
